ns.NEWS = {
	{ version = "1.5.0", date = "2026-11-21", blocks = {
		{ "h", "New: What's new" },
		{ "b", "After an update, a window shows once with what changed since the version you last saw: this list, newest first. It never opens in a fight or over another window, and a new install doesn't show it.", 1 },
		{ "b", "|cffffd200Never show again|r at its top right turns it off for good (it's never ticked for you). Type /fct whatsnew to see this version's notes and turn it back on.", 1 },
		{ "h", "New: a ring remembers your last pick" },
		{ "b", "|cffffd200Middle|r, a new setting per ring in the Rings tab: |cffffd200Cancel|r (the default, as before) or |cffffd200Use last|r. With Use last, letting go of a Hold ring in the middle, or pressing |cffffd200Cross|r with nothing aimed, uses the slot you used last. Handy for totem and buff rings.", 1 },
		{ "b", "The buttons that open the ring (crossbar, Bindings, touch buttons) show that slot's icon, and so does the ring's middle while nothing is aimed.", 1 },
		{ "b", "Each character remembers its own last pick, across reloads. Change or empty that slot and it's forgotten.", 1 },
		{ "b", "Switch it from any button that opens the ring too: |cffffd200Triangle|r on the cell in Bindings (or on a touch button) shows |cffffd200Middle: Cancel|r / |cffffd200Middle: Use last|r. It's the ring's own setting, shared by every button that opens it.", 1 },
		{ "b", "A Toggle ring still opens on its button and closes on it again; |cffffd200Circle|r still cancels.", 1 },
		{ "h", "New: an arrow on ring buttons" },
		{ "b", "Every button that opens a ring has the game's small flyout arrow at its top edge, on the crossbar, in Bindings and on touch buttons, so you can tell them apart. Healer mode buttons keep their green cross instead.", 1 },
		{ "b", "The arrow hides while that ring is open, as the game's own flyout arrows do.", 1 },
		{ "b", "On by default. Turn it off with |cffffd200Arrow on ring buttons|r at the foot of the ring list in the Rings tab.", 1 },
		{ "h", "New: Healer mode remembers your last target" },
		{ "b", "In |cffffd200Bindings|r, on a button in Healer mode, |cffffd200Triangle|r shows |cffffd200Middle: Cancel|r under the Healer mode row. Pick it for |cffffd200Middle: Last target|r: letting go in the middle then casts on the place you last healed with that button, like Party 2.", 1 },
		{ "b", "While you hold the ring with the stick in the middle, that place lights up and shows its tooltip. If that unit can't be helped now (gone, hostile), nothing is cast.", 1 },
		{ "b", "It remembers the place, not the person, per button and per character. Off by default.", 1 },
		{ "h", "New: L3 and R3 in Bindings" },
		{ "b", "|cffffd200L3|r and |cffffd200R3|r (pressing a stick) have their own rows in Bindings, with a cell per bar, like a back paddle: put anything from the picker on L3 alone, on |cffffd200L2 + R3|r and so on. Rings opened from a stick press aim with the other stick when set to Dynamic.", 1 },
		{ "b", "A stick press is taken over only while one of its bars holds an action. Clear every bar and it's the game's again: |cffffd200L3|r auto-runs, |cffffd200R3|r pings. While one bar is used, the empty bars of that stick do nothing.", 1 },
		{ "b", "Until then its cells show what the game does with it, |cffffd200Auto-run|r or |cffffd200Ping|r, with the game's own icon, like the face buttons' Jump and Interact.", 1 },
		{ "h", "New: sort your bags with a stick press" },
		{ "b", "While your bags are open, |cffffd200L3|r sorts them. With the bags closed it works as usual (Auto-run). Not with a shoulder or trigger held.", 1 },
		{ "b", "The bags' controller footer shows it: an |cffffd200L3 Sort|r prompt joined to the end of Select · Collapse · Manage Bag · Close.", 1 },
		{ "b", "|cffffd200Tweaks → Bags & vendors → Sort bags key:|r L3 (the default), R3 or Off. This is the one tweak that starts on, so the Tweaks tab now says most are off until you turn them on.", 1 },
		{ "h", "New: your settings on every computer" },
		{ "b", "Play on a Mac and a handheld? Your bindings, rings, touch bars, controller setup, tweaks and keyboard settings (quick messages included) now follow you. The addon keeps a copy in a few account macros, |cffffd200FCT:Sync 1|r, |cffffd200FCT:Sync 2|r…, which the game stores for your account, and every computer you log in on uses the newest copy. On by default.", 1 },
		{ "b", "Each part goes on its own: change your rings on one computer and your tweaks on the other, and both arrive. When the same part changed on both, the newer one wins, chat says so, and |cffffd200Undo last sync|r brings yours back.", 1 },
		{ "b", "The first time on a computer that already has its own setup, it asks once: |cffffd200Use synced|r or |cffffd200Keep mine|r. Either way the other copy is kept for |cffffd200Undo last sync|r. A computer that hasn't read the synced copy yet never writes over it.", 1 },
		{ "b", "What stays on each computer: the keyboard's learned words, which slot a ring used last, Healer mode's last target, and the addon's own bookkeeping.", 1 },
		{ "b", "Bindings are kept per controller. A controller with no bindings yet offers |cffffd200Copy bindings from|r your other controller.", 1 },
		{ "b", "|cffffd200Triangle → More → Sync & backup|r on any tab shows when it last synced and from where, how many macros it uses and how many are free, and turns it off for this computer (the macros stay for the others). The same switch is in |cffffd200Tweaks → Controller → Sync between machines|r. /fct sync shows the same in chat; /fct sync now, on, off and undo do what they say.", 1 },
		{ "b", "The sync macros do nothing if pressed. Don't edit them in the Macros window; if one is changed or deleted, the addon writes them again. It never deletes a macro of yours, even one named FCT:Sync, and it never writes half a copy: when your account macros are full it says how many to free. /fct release deletes them too.", 1 },
		{ "h", "New: export and import" },
		{ "b", "|cffffd200Sync & backup → Export…|r (or /fct export) shows your settings as text, already selected: Ctrl+C (Cmd+C on a Mac) copies it. It holds this character's bindings for this controller, touch bars, rings, tweaks, keyboard settings, options and the controller layout, and no character names, so you can share it.", 1 },
		{ "b", "|cffffd200Import…|r (or /fct import): paste with Ctrl+V (Cmd+V). It lists what would change, part by part; untick what you want to keep. Import asks once, and |cffffd200Undo last sync|r puts your old settings back. Pasting needs a keyboard.", 1 },
		{ "h", "Fixes" },
		{ "b", "|cffffd200No more piles of FCT: macros:|r the addon could lose track of one of its own macros (playing on a second computer, its settings reset, or a check at login that ran before the macro list had loaded) and then made \"FCT:Bags 2\", \"FCT:Bags 3\"… beside it, for game actions and other addons' buttons alike, filling the hidden action slots until touch buttons couldn't be added. It now recognises its own macros by name and text and reuses them, and a hidden slot that already holds the action a button wants (placed from your other computer) is reused instead of taking another. Once per login it also tidies what earlier versions left: one copy of each is kept, your buttons point at it, the extra copies are deleted and the hidden slots they held are freed. |cffffd200/fct cleanup|r does it on demand and says what it did. Your own macros are never touched, even one named FCT:.", 1 },
		{ "b", "|cffffd200Hidden action slots are shared between your computers and freed when no binding uses them.|r The addon now keeps a list of the hidden slots (keyboard bars 6-8) it placed on any of your computers, in the sync macros. A computer reuses a slot the other one placed for the same action, and frees one that no binding or touch button of that character uses any more, on any controller. Slots holding your own actions are never touched. Two buttons with the same action now share one hidden slot.", 1 },
		{ "b", "|cffffd200Touch buttons when every hidden slot is taken:|r adding an action no longer fails. It works right away as a macro, without a live cooldown or charges until a hidden slot frees up (its tooltip says so), then it gets one by itself.", 1 },
		{ "b", "|cffffd200Free up slots|r in the Touch tab: when your own actions sit on keyboard bars 6-8 (the hidden slots touch buttons and moved actions use), a button next to the slot counter lists them and, after you confirm, clears them from those bars. The spells, items and macros themselves stay.", 1 },
		{ "b", "|cffffd200Sort bags button:|r it could disappear behind the combined bags' title bar in the Gamepad UI. It now sits at the right end of the title bar and stays there.", 1 },
		{ "b", "|cffffd200Crossbar stuck after a held ring:|r with a modifier moved to another button (for example the right bar on L1), the crossbar could stay on that bar after a held ring or a heal, until you pressed the modifier again. It now always goes back.", 1 },
		{ "b", "|cffffd200Ring buttons showed an item count:|r a ring on a crossbar slot that held food or another stack showed that item's count on the ring's icon. The count is hidden now.", 1 },
		{ "b", "|cffffd200Aiming a heal with the left stick:|r after a held ring closes, the stick that aimed it stays held back while you cast or channel, so a heal aimed with the left stick isn't broken by walking. It's let go as soon as the stick is back in the middle, and a second after the cast ends at the latest.", 1 },
	} },
	{ version = "1.4.0", date = "2026-11-17", blocks = {
		{ "h", "New: Healer mode" },
		{ "p", "Any button that holds a heal can open a ring of your group: aim at someone and let go to cast on them." },
		{ "b", "|cffffd200On per button:|r focus a cell in Bindings (or a touch button in the Touch tab), press |cffffd200Triangle|r and pick |cffffd200Healer mode: On|r. Spells, spell groups and items can use it. A green cross marks the button in the windows and on your crossbar.", 1 },
		{ "b", "|cffffd200The ring:|r the game's small round picker on the button you hold, with 7 places in fixed spots: You, Party 1 to 4, Target and Focus. Let go on someone to cast there, in the middle to cast nothing. Dead allies can be picked for a resurrection; a hostile target can't.", 1 },
		{ "b", "|cffffd200Each place|r shows the portrait, a health ring in the class colour, the role, incoming heals, shields, heal absorbs, a red pulse under 30% health, and a debuff you can dispel. The person you aim at gets the game's own tooltip.", 1 },
		{ "b", "Works on face buttons, the D-pad, paddles, crossbar slots and touch buttons, in combat too. No settings: it always shows while held and aims with the stick for that button.", 1 },
	} },
	{ version = "1.3.0", date = "2026-11-15", blocks = {
		{ "h", "New: the Tweaks tab" },
		{ "p", "A fifth settings tab with small conveniences for every character. |cffffd200Each one is off until you turn it on|r, and they work only while the Gamepad UI is on." },
		{ "b", "|cffffd200Bags & vendors|r", 1 },
		{ "b", "|cffffd200Sort bags button:|r a Sort button on your bags' title bar. With the controller, use Clean Up in the bag menu or the picker's |cffffd200Sort bags|r action.", 2 },
		{ "b", "|cffffd200Sell junk:|r sells your grey items when you talk to a merchant. One chat line lists what sold and for how much.", 2 },
		{ "b", "|cffffd200Repair:|r repairs your gear at a merchant who repairs. |cffffd200Use guild funds first|r pays from the guild bank when the guild allows it.", 2 },
		{ "b", "|cffffd200Buy a full stack:|r a Stack button on stackable merchant items, and a picker action that buys a stack of the item under the cursor. It never spends 150 gold or more in one press, and says when the item is sold out.", 2 },
		{ "b", "|cffffd200Quests & NPCs|r", 1 },
		{ "b", "|cffffd200Skip one-option talk:|r when an NPC offers only one thing, it's picked for you: a single quest, or a vendor, trainer, flight map or bank. Never a teleport, an event start, a story skip or an option that costs money.", 2 },
		{ "b", "|cffffd200Trainer: Learn all:|r a Learn all button for every skill you can afford.", 2 },
		{ "b", "|cffffd200Mail: Open all:|r an Open all button on the mailbox. It skips cash-on-delivery mail and stops when your bags are full.", 2 },
		{ "b", "|cffffd200Rumble:|r the controller rumbles on events, in eight groups, each with its own pattern (or Off), and one |cffffd200Strength|r for all. See below.", 1 },
		{ "b", "|cffffd200Controller|r", 1 },
		{ "b", "|cffffd200Low battery warning:|r one chat line when the controller's battery runs low.", 2 },
		{ "b", "|cffffd200Battery on the minimap:|r a round button on the minimap's ring, next to the others, with the controller's charge. Hidden for pads that don't report one.", 2 },
		{ "b", "|cffffd200Rare nearby alert:|r a line on screen and a rumble when a rare is near. Once per rare, never in a fight.", 2 },
		{ "b", "|cffffd200Light bar:|r Game default, Class colour or Custom (10 colours), plus |cffffd200Combat flash|r (red while you're in combat). For pads with a light bar; Steam may take it over.", 2 },
		{ "b", "|cffffd200Loot & gear|r", 1 },
		{ "b", "|cffffd200Fast loot:|r takes all loot at once. Bind-on-pickup items still ask; with full bags only coins are taken.", 2 },
		{ "b", "|cffffd200Pass on unusable rolls:|r passes on armour or weapons your class can never use. When unsure, you roll.", 2 },
		{ "b", "|cffffd200Upgrade arrows:|r a green arrow on gear in your bags, the loot window and loot rolls that has a higher item level than what you wear there.", 2 },
		{ "b", "|cffffd200Wear quest rewards:|r after a quest, an upgrade reward gets a card for 10 seconds: hold the top face button 1 to 3 seconds to wear it.", 2 },
		{ "b", "|cffffd200Group & social|r", 1 },
		{ "b", "|cffffd200Accept friend & guild invites:|r joins a group when a friend, Battle.net friend or guild member invites you. Never a role check, a quest session invite, or an invite that would drop your dungeon or PvP queue.", 2 },
		{ "b", "|cffffd200Decline duels:|r turns down every duel request.", 2 },
		{ "b", "|cffffd200Accept resurrect and summon:|r out of combat. A resurrection only without resurrection sickness. A summon only from a friend or guild member, and never while you're inside an instance.", 2 },
		{ "b", "|cffffd200Whisper alert:|r a card with who whispered you and how the message starts.", 2 },
		{ "h", "Rumble" },
		{ "b", "The groups and their starting patterns: |cffffd200Group|r (ready check, invite, summon, resurrect: Double tap), |cffffd200Whisper|r (Tap), |cffffd200Trade & duel|r (Tap), |cffffd200Danger|r (death, stun or fear, aggro, interrupted cast: Long buzz), |cffffd200Enemies|r (an enemy player nearby: Double tap), |cffffd200Rare nearby|r (Heartbeat), |cffffd200Level ups|r (level up, achievement: Ramp up) and |cffffd200Procs|r (a spell lights up, your target dies, you land a critical strike (solo): Off).", 1 },
		{ "b", "Patterns: Tap, Double tap, Triple tap, Long buzz, Heartbeat, Ramp up, Fade out, or Off. Cross on a group's row plays its pattern; Cross on Strength plays a Double tap.", 1 },
		{ "b", "Only events you still have to answer rumble: an invite a tweak accepted doesn't.", 1 },
		{ "b", "Busy events wait before they rumble again: whispers, invites and trades 3 seconds, procs 2, critical strikes 1, aggro 3, enemy players 10.", 1 },
		{ "b", "The light motor never runs below half power, so every pattern can be felt.", 1 },
		{ "h", "New picker actions" },
		{ "b", "|cffffd200Combat:|r |cffffd200Cancel|r (stops a cast, a ground target and clears your target), |cffffd200Best healing potion|r, |cffffd200Best mana potion|r, |cffffd200Best grenade|r. They work in combat.", 1 },
		{ "b", "|cffffd200Movement:|r |cffffd200Look behind (hold)|r: the camera turns round while you hold the button.", 1 },
		{ "b", "|cffffd200Windows:|r |cffffd200Peek map (hold)|r: the map shows while you hold the button.", 1 },
		{ "b", "|cffffd200Targeting:|r |cffffd200Mark next|r: the next raid mark on your target, in kill order (skull, cross, square…), in combat too.", 1 },
		{ "b", "|cffffd200Misc:|r |cffffd200Sort bags|r, |cffffd200Buy a full stack|r, |cffffd200Eat & drink|r (your best food, and drink if you use mana), |cffffd200Quest item|r (the item of the quest you follow, else the nearest one), |cffffd200Track nearest quest|r (again for the next nearest), |cffffd200Ready check|r, |cffffd200Pull countdown (5 s)|r and |cffffd200Minimap zoom|r.", 1 },
		{ "b", "The two hold actions work on face, D-pad and paddle buttons. On a touch button or ring slot a tap toggles them.", 1 },
		{ "b", "The potion, grenade and food actions find items by their English names, so they need an English game client.", 1 },
		{ "h", "Rings" },
		{ "b", "|cffffd200The native radial look:|r rings now look like the game's own radial menu, with just the wheel: no title and no band. The Rings tab shows the same wheel.", 1 },
		{ "b", "|cffffd200Let go of the stick to use the slot.|r Letting go of the button and the stick at the same moment uses it too.", 1 },
		{ "b", "|cffffd200Show, per ring: Toggle or Hold.|r", 1 },
		{ "b", "|cffffd200Toggle|r (the default): a press opens the ring, and it stays until you use a slot, press its button again or press Circle.", 2 },
		{ "b", "|cffffd200Hold:|r the ring shows while you hold the button. Let go to use the slot you aim at; with nothing aimed it just closes.", 2 },
		{ "b", "New rings aim with the |cffffd200Right|r stick.", 1 },
		{ "b", "Fixed: a ring could get stuck on a diagonal, or stay open with nothing used.", 1 },
		{ "b", "A held ring opened with the stick already pushed ignores that slot until the stick is centred again or moves off it.", 1 },
		{ "b", "A ring released with nothing picked stays open (Toggle), so you can still aim.", 1 },
