	{ version = "1.2.1-beta.2", date = "2026-11-14", blocks = {
		{ "h", "Rings" },
		{ "b", "|cffffd200Let go of the stick to use a slot|r, like the game's own radial menu: press the ring's button, flick the stick to a slot, let the stick go. Works in combat.", 1 },
		{ "b", "The ring stays open when you let go of its button with the stick centred. |cffffd200A|r uses the lit slot; |cffffd200B|r, a stick press or the ring's button again closes it without using anything. Letting go of the button while aiming still uses the slot.", 1 },
		{ "b", "While a held ring is open, the addon turns on the game's stick-as-buttons setting (GamePadStickAxisButtons) and puts your own value back when it closes (after combat if a fight is on, or at the next login after a /reload).", 1 },
		{ "b", "The ring's |cffffd200Rename|r box saves with the on-screen keyboard's Send and cancels with Close.", 1 },
		{ "h", "Keyboard" },
		{ "b", "|cffffd200Your own quick messages:|r Keyboard tab → |cffffd200Quick messages|r. Pick a situation (or |cffffd200Always|r), add, edit, delete and reorder up to 20 lines, typed with the on-screen keyboard. They come first in that situation's suggestions, fill-ins such as {target} work, and |cffffd200Show in suggestions|r can hide the built-in lines. Reset keyboard to defaults keeps them.", 1 },
	} },
	{ version = "1.2.1-beta.1", date = "2026-11-14", blocks = {
		{ "h", "Fixes" },
		{ "b", "Removed |cffffd200Open chat|r: opening chat from an addon broke the Gamepad UI (\"blocked from an action\" error). Tap the chat box or use the game's own chat key instead.", 1 },
		{ "b", "A button that still holds Open chat from 1.2.0 now does nothing and no longer errors. Pick a new action for it.", 1 },
		{ "b", "Keyboard: fixed \"ForeverControllerTweaks_Keyboard has been blocked\" (SetPreferredGamepadInteractTarget) after using bag search and closing it. The keyboard no longer presses a box's Enter or Escape itself.", 1 },
		{ "b", "Keyboard: |cffffd200B|r after Send or Close leaves the chat box or bag search through the game's own Back, so the box closes too. Close (Y) keeps the box and its text.", 1 },
		{ "b", "Keyboard: Send in chat needs Chat Style |cffffd200IM|r (Options → Social). With Classic it says so; close the keyboard and press A to send.", 1 },
		{ "b", "Keyboard: tapping a text box on screen (Steam Link) opens the keyboard while your touch bars are on.", 1 },
		{ "b", "Keyboard: chat can no longer end up on the \"needs a real keyboard\" list.", 1 },
		{ "h", "Added" },
		{ "b", "|cffffd200Toggle FPS|r action in the picker's Misc category: shows or hides the game's framerate counter. Works on face, D-pad and paddle buttons, touch buttons and ring slots.", 1 },
		{ "b", "|cffffd200Scrolling suggestions:|r the list goes on past the first screen, up to 40 rows. Scroll with the D-pad or the mouse wheel; arrows show when there's more.", 1 },
		{ "b", "|cffffd200Real answers:|r when someone asks \"what lvl?\", \"what spec?\", \"where r u?\", \"tank or heal?\", \"how far?\" or \"ilvl?\", the top suggestion is your actual answer: \"18 Restoration Shaman\", \"Thunder Bluff, near 39, 55\", \"2/3 Kuz's Skull\", \"Item level 24\".", 1 },
		{ "b", "|cffffd200Whole-line completion:|r type 3 letters and get full lines, your own sent lines first, then phrases for where you are. One typo per word is forgiven (\"anyoen\" still finds \"anyone\").", 1 },
		{ "b", "|cffffd200Reactions:|r short-lived lines for what just happened: level up (\"Ding 19!\"), an achievement, a boss kill (\"gg\") or wipe (\"Wipe, run back\"), a rare or better drop, and a buff another player cast on you (\"Thanks for the Fortitude!\", once per player and buff every 5 minutes).", 1 },
	} },
	{ version = "1.2.0-beta.1", date = "2026-11-14", blocks = {
		{ "h", "Modules" },
		{ "b", "Touch bars, the on-screen keyboard and action rings are now separate modules: |cffffd200Forever Controller Tweaks: Touch|r, |cffffd200: Keyboard|r and |cffffd200: Rings|r. They're in the same download and listed under Forever Controller Tweaks in the AddOns list, on by default.", 1 },
		{ "b", "Turn off the ones you don't use in the AddOns list, then /reload. Their tab, More and Options entries and commands go away; their settings stay saved for when you turn them back on.", 1 },
		{ "b", "The main addon works on its own. A button holding |cffffd200Open ring|r while Rings is off does nothing, and shows greyed with a note.", 1 },
		{ "b", "Tabs keep their order (Bindings, Touch, Keyboard, Rings), and the L1/R1 hints name the tab next door.", 1 },
		{ "b", "Installing by hand: copy all four folders (ForeverControllerTweaks and the three ForeverControllerTweaks_* folders). Your settings, rings, keyboard words and touch bars carry over unchanged.", 1 },
		{ "h", "Added" },
		{ "b", "|cffffd200Open chat|r action for any button: in the picker's Windows category, for face, D-pad and paddle cells, touch buttons and ring slots. It opens the chat box like Enter on a keyboard, and the on-screen keyboard follows if its module is on.", 1 },
		{ "h", "Keyboard" },
		{ "b", "Channel switches work again: /s, /y, /p, /raid, /i, /g, /o, /w Name, /r and /1–/10. Other slash commands still need a real keyboard.", 1 },
		{ "b", "The keyboard's channel keys switch the channel at once and leave your typed text in place.", 1 },
		{ "b", "Sending a message closes the keyboard; it opens again the next time you open chat.", 1 },
		{ "b", "Suggestions too long for the list show in full in a tooltip when focused or hovered.", 1 },
	} },
	{ version = "1.1.1-beta.1", date = "2026-11-14", blocks = {
		{ "h", "Back paddles as action buttons" },
		{ "b", "A back paddle (Xbox Elite, DualSense Edge) without a role is now an action button, with its own action on each bar like a face button: for example Jump on the paddle alone and a heal on RT + paddle.", 1 },
		{ "b", "Anything from the action picker works there: spells (ranks and Highest Rank), items, toys, mounts, equipment sets, macros, Jump, Interact, Back, Inspect, game actions, other addons' bindings and |cffffd200Open ring|r.", 1 },
		{ "b", "Set a paddle's role to |cffffd200None|r to use it for actions; give it a role to make it a modifier again. Its actions stay saved while it has a role.", 1 },
		{ "b", "Paddles with a role work exactly as before.", 1 },
		{ "b", "Paddles are now named |cffffd200Back paddle 1–4|r.", 1 },
	} },
	{ version = "1.1.0-beta.1", date = "2026-11-13", blocks = {
		{ "p", "Two big additions, an on-screen keyboard and action rings, plus touch bar modifier pages and a cleaner settings window. Still a beta: please report anything odd with /fct selftest." },
		{ "h", "On-screen keyboard (new)" },
		{ "b", "A radial keyboard in WoW Forever's style opens on any text box while the Gamepad UI is on: chat, whispers, bag search, mail, macros, the auction house and more. Choose whether it opens only when you use the controller, or always.", 1 },
		{ "b", "Both sticks type: each stick picks a cluster of four letters, the face buttons pick the letter. L1 is Shift, L2 is Symbols, and the hub has Space, Send, Erase and Close. Every button can be rebound.", 1 },
		{ "b", "It places itself on the line from the text box toward the screen centre, clear of the chat window, the crossbar, your unit frame and the touch bars. Or pin it to the centre, or to a custom offset.", 1 },
		{ "b", "|cffffd200Smart suggestions|r, all offline in the game:", 1 },
		{ "b", "263 hand-written lines across 25 situations (ready check, resurrect, summon, invite, trade, duel, loot roll, dungeon, raid, battleground, city, guild and more), with fill-ins such as {zone}, {quest}, {target}, {class}, {role} and {level}.", 2 },
		{ "b", "Replies to chat aimed at you: 25 intent rules recognise 125 phrases (\"inv?\", \"LF healer\", \"ready?\", \"res pls\"…), and the reply goes back on the right channel. \"I can heal\" only shows if you can.", 2 },
		{ "b", "Quest progress for the quest you follow: \"Need 5 more Wolf Pelts\", \"Done with {quest}, turning in\". At most two quest lines.", 2 },
		{ "b", "Next-word prediction like a phone keyboard: after \"Hello \" it offers \"everyone\", \"there\", \"all\". It starts with built-in word pairs and learns how you write. R1 inserts a word and a space, so repeated R1 presses build a sentence.", 2 },
		{ "b", "Shorthands expand: lf, lfm, brb, omw, wts, oom, ty…", 2 },
		{ "b", "Each kind of box gets its own list: item names in bag search, names in mail \"To\" and /who, nothing in number boxes, word suggestions only in mail and macro text.", 2 },
		{ "b", "Nothing is ever sent for you, and nothing leaves your PC. Only your own sent messages are learned from; other players' lines are kept for three minutes at most and never saved.", 1 },
		{ "b", "Boxes the game blocks addons from typing into (the Options search, the Group Finder's boxes, spellbook search) are left to the real keyboard, with a one-line note instead of an error. Slash commands in chat (anything starting with /) are left to the real keyboard too.", 1 },
		{ "h", "Action rings (new)" },
		{ "b", "Make your own radial menus: up to 12 rings of 4–12 slots, each with a name and an icon from the game's full macro icon set.", 1 },
		{ "b", "Fill the slots from the same action list as the bindings: spells (with Highest Rank), items, toys, mounts, macros, game actions and other addons' bindings.", 1 },
		{ "b", "Put \"Open ring\" on any face, D-pad or touch button, on any bar. Hold the button, aim with the stick, release to use; release with the stick centred to cancel. Works in combat.", 1 },
		{ "b", "Choose the aiming stick per ring: |cffffd200Right|r, |cffffd200Left|r, or |cffffd200Dynamic|r (the stick of the hand that isn't on the button). The other stick keeps moving or looking, and the aiming stick is held back after release until it's centred, so you don't walk off.", 1 },
		{ "b", "Slots show cooldowns, charges, range and usability. Touch rings open with a tap and fire with a tap.", 1 },
		{ "b", "Rings don't use any hidden action slots.", 1 },
		{ "h", "Bindings and modifiers in one screen" },
		{ "b", "The |cffffd200Modifiers|r tab is merged into |cffffd200Bindings|r: L1, L2, R1, R2 and the paddles are rows at the top of each side. Press A to give a button a role; picking a role another button has swaps the two.", 1 },
		{ "b", "Presets (|cffffd200Game default|r, |cffffd200Left = bars, Right = targeting|r) are first in Triangle → More, and the header names the active one.", 1 },
		{ "b", "The guided \"set it up yourself\" step runs on the Bindings screen.", 1 },
		{ "b", "Tabs are now |cffffd200Bindings|r, |cffffd200Touch|r, |cffffd200Keyboard|r and |cffffd200Rings|r.", 1 },
		{ "h", "Touch bars" },
		{ "b", "Modifier pages: each touch button has an action per bar (top, left, right, bottom), following your modifiers. An empty page hides its button instead of falling back.", 1 },
		{ "b", "Settings per side: count, size, spacing, distance from the edge, height, opacity, |cffffd200Circle|r or |cffffd200Square|r buttons, and |cffffd200Hide|r or |cffffd200Show|r empty buttons.", 1 },
		{ "h", "Look and feel" },
		{ "b", "Every screen has Triangle = |cffffd200More|r, with one shared menu.", 1 },
		{ "b", "Calm, textured window background in WoW Forever's stone style, with translucent content boxes on every tab.", 1 },
		{ "b", "New controller drawing in the logo's style. Only the focused row's button lights, never a button you're physically pressing.", 1 },
		{ "b", "Controller type cards show each family's own layout and glyphs; the \"Choose your layout\" screen is redrawn to match.", 1 },
		{ "h", "Fixes" },
		{ "b", "The \"no controller found\" line no longer sticks when a pad wasn't readable at login, and /fct selftest now lists what every controller reports.", 1 },
	} },
	{ version = "1.0.0-beta.1", date = "2026-11-12", blocks = {
		{ "p", "First public beta, for WoW Forever 1.60.1 (Interface 16001). Everything works, but not many people have played it yet, so please report anything odd." },
		{ "h", "Modifiers and targeting" },
		{ "b", "Give the left bar, right bar, friendly targeting and hostile targeting to any of L1, R1, L2, R2 or the back paddles P1–P4. Picking a role another button already has swaps the two.", 1 },
		{ "b", "Presets: |cffffd200Game default|r and |cffffd200Left = bars, Right = targeting|r, plus a guided \"set it up yourself\" mode that asks for one button per role.", 1 },
		{ "b", "Works through the game's own controller config, so every native bar, glyph and targeting mode keeps working.", 1 },
		{ "b", "Game windows (bags, talents, map) get the game's own L1/R1 tabs back while they're open, out of combat.", 1 },
		{ "b", "Combat-safe: the settings window closes when combat starts, and your layout stays in place for the whole fight. The controller config never switches while a button or trigger is held.", 1 },
		{ "b", "Logging out, /reload, disabling the addon or turning off the Gamepad UI leaves a clean, default controller config. A config left by a logout in combat is cleaned up at the next login.", 1 },
		{ "b", "If another addon already owns the controller config, Forever Controller Tweaks keeps a copy and restores it.", 1 },
		{ "h", "Bindings" },
		{ "b", "The settings open on the |cffffd200Bindings|r tab: the controller drawn in the middle, one row per button at the edges, with that button's action on the top, left, right and bottom bar. The focused row draws a gold line to its button.", 1 },
		{ "b", "Any action on any face or D-pad button, on any bar: spells, pet spells, items, toys, mounts, equipment sets, your macros, game actions, and Jump, Interact, Back and Inspect. Interact keeps hold-to-loot, and Jump keeps swim up.", 1 },
		{ "b", "Moved actions behave like native slots: cooldowns, range, mana, charges, proc glow, tooltips, the press look and mouse clicks.", 1 },
		{ "b", "Crossbar pages 1–3, switched with L2/R2. A note shows when a stance or pet bar replaces a bar on a page.", 1 },
		{ "b", "Action picker: L1/R1 switch categories, L2/R2 page through long lists, Square clears a slot and Triangle undoes the clear. Entries that can't go on a button are greyed out with the reason.", 1 },
		{ "b", "Spells with ranks are grouped, with a ranks page. |cffffd200Highest Rank|r moves up by itself when you learn a new rank.", 1 },
		{ "b", "|cffffd200AddOns|r category: any key binding another addon registers (for example WellMet) can go on a controller button.", 1 },
		{ "b", "Game actions (Bags, Map, Target nearest enemy, Extra action and more) are FCT: macros, tracked per character across the account. Macros you made yourself are never touched.", 1 },
		{ "b", "Moved actions are stored in empty slots of keyboard action bars 6–8 (slots 145–180), which the Gamepad UI never shows, and freed when you clear the button.", 1 },
		{ "h", "Touch bars" },
		{ "b", "Two bars of tap buttons on the left and right screen edges, for Steam Link on a phone or tablet. Off by default.", 1 },
		{ "b", "The |cffffd200Touch|r tab sets 1–12 buttons per bar, their size, spacing, distance from the edge, height and opacity, with a live preview, and when they show: always, with the Gamepad UI, in combat, or never.", 1 },
		{ "b", "Touch buttons look and behave like native crossbar slots.", 1 },
		{ "h", "Glyphs" },
		{ "b", "Bar hints, class prompts, the on-screen legend and the targeting markers show the buttons you press. With both targeting roles on one side, the marker splits into a friendly and a hostile half.", 1 },
		{ "b", "Moved actions show their icon on their new button, pressed in like a native slot.", 1 },
		{ "b", "Xbox letters, PlayStation shapes and Nintendo glyphs follow the active controller and switch live.", 1 },
		{ "b", "A one-time notice explains that the world's Interact prompts keep the game's default button, and how to hide them.", 1 },
		{ "h", "Controllers" },
		{ "b", "DualSense, DualShock 4, Xbox, Switch Pro and Steam Input virtual pads are recognised by vendor or by the game's button style.", 1 },
		{ "b", "An unrecognised pad gets controller type cards: PlayStation, Xbox, Switch or Custom. On Steam Link, Xbox is suggested.", 1 },
		{ "b", "Controller setup (/fct detect): a guided \"press each button\" wizard that teaches the game every button of an unknown controller, then lets you pick its glyph style. A rejected press names the step that already uses it. Reset detection undoes it.", 1 },
		{ "b", "Several pads, or Steam mirroring a physical pad: the addon follows the pad you're pressing.", 1 },
		{ "b", "Each controller keeps its own layout. |cffffd200Not now|r in the first-start guide is remembered per controller.", 1 },
		{ "h", "Settings windows" },
		{ "b", "Three tabs, |cffffd200Bindings|r, |cffffd200Modifiers|r and |cffffd200Touch|r, in WoW Forever's own window look, switched with L1/R1.", 1 },
		{ "b", "Driven entirely with the D-pad, with a focus cursor, tooltips and footer hints.", 1 },
		{ "b", "First-start guide: welcome, choose your layout, try it, face actions, done.", 1 },
		{ "b", "Open them on the controller (hold L2 + R2, press Create, View or Minus), from the addon's minimap button, the minimap AddOns menu, Options → AddOns → Forever Controller Tweaks (Open Settings, Run setup guide), a key binding or /fct (/controllertweaks).", 1 },
		{ "b", "Opened from Options, the Options window goes invisible underneath and comes back when you close the settings.", 1 },
		{ "b", "Windows scale down to fit small or 4:3 screens and large UI scales.", 1 },
		{ "b", "/fct selftest collects details for bug reports. /fct release clears the addon's hidden slots and FCT: macros before you uninstall.", 1 },
	} },
}
